void baseline_cache::cycle() {
  if (!m_miss_queue.empty()) {
    mem_fetch *mf = m_miss_queue.front();
    if (!m_memport->full(mf->size(), mf->get_is_write()) &&
        lower_ready(mf, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle)) {
      m_miss_queue.pop_front();
      m_memport->push(mf);
      lower_accepted(mf, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
    }
  }
  bool data_port_busy = !m_bandwidth_management.data_port_free();
  bool fill_port_busy = !m_bandwidth_management.fill_port_free();
  // Keep the characterization observation aligned with the native statistics.
  // This is intentionally before replenish_port_bandwidth(); it must not affect
  // availability, admission, or fill semantics later in this cache cycle.
  m_l2_char_data_port_busy_snapshot = data_port_busy;
  m_l2_char_fill_port_busy_snapshot = fill_port_busy;
  m_stats.sample_cache_port_utility(data_port_busy, fill_port_busy);
  m_bandwidth_management.replenish_port_bandwidth();
}

bool l2_cache::lower_ready(mem_fetch *mf, unsigned long long cycle) {
  if (!ft_enabled() || mf->get_access_type() != L2_WRBK_ACC) return true;
  std::map<mem_fetch *,ft_wb_record>::iterator it = m_ft_wb.find(mf);
  assert(it != m_ft_wb.end());
  const ep_l2_payload_store::request_result result = m_ep_l2_payload.request(
      it->second.handle, false, cycle, (unsigned long long)-1, ep_l2_payload_store::WB_READOUT);
  if (result != ep_l2_payload_store::GRANTED) { ++m_ft_stats.bank_block; return false; }
  assert(m_ep_l2_payload.inspect(it->second.handle).versions == it->second.expected);
  m_ft_last_wb_versions = it->second.expected;
  mf->set_ft_wb_data(it->second.expected);
  ++m_ft_stats.staging_reads; ++m_ft_stats.data_checks;
  return true;
}

request_result request(role r, unsigned id, bool write, unsigned long long cycle,
                       unsigned long long sequence = (unsigned long long)-1,
                       operation_class op_class = RESIDENT_HIT_READ) {
  if (!enabled()) return GRANTED;
  if (m_ft_mode && m_cycle != (unsigned long long)-1)
    assert(cycle >= m_cycle && "FT bank clock must be physical and monotonic");
  if (m_cycle != cycle) {
    m_cycle = cycle;
    m_resident_reads = m_resident_writes = m_bypass_reads = m_bypass_writes = 0;
    m_bank_granted.reset();
    if (banked()) {
      for (unsigned b = 0; b < 4; ++b) {
        // A production retry need not return in the single cycle after it
        // was selected.  Retain an unconsumed oldest grant until its owner
        // actually retries; clearing it here loses the request.  Two
        // interleaved same-bank retries would otherwise select-and-discard
        // each other forever, eventually deadlocking the memory system.
        if (!m_granted[b].empty()) continue;
        if (m_pending[b].empty()) continue;
        unsigned best = 0;
        for (unsigned i = 1; i < m_pending[b].size(); ++i)
          if (m_pending[b][i].sequence < m_pending[b][best].sequence) best = i;
        m_granted[b].push_back(m_pending[b][best]);
        m_pending[b].erase(m_pending[b].begin() + best);
      }
    }
  }
  if (m_mode == 1) {
    unsigned &used_port = r == RESIDENT ?
        (write ? m_resident_writes : m_resident_reads) :
        (write ? m_bypass_writes : m_bypass_reads);
    if (used_port) return LEGACY_PORT_BUSY;
    ++used_port; return GRANTED;
  }
  const unsigned global_id = r == BYPASS ? k_resident_slots + id : id;
  assert(global_id < m_slots.size());
  const unsigned bank = global_id % 4;
  ++m_bank_attempts;
  if (!m_granted[bank].empty()) {
    const pending_op op = m_granted[bank].front();
    if (op.r == r && op.id == id && op.write == write) {
      // Its first call was accounted as the logical operation.  This call
      // is the retry that finally consumes an oldest-ready grant.
      ++m_bank_retry_attempts;
      m_granted[bank].clear(); m_bank_granted.set(bank); ++m_bank_grants;
      ++m_bank_grants_by_bank[bank];
      if (op.true_conflict) {
        const unsigned long long waited = cycle - op.first_conflict_cycle;
        m_bank_wait_cycles += waited;
        m_bank_wait_cycles_by_bank[bank] += waited;
      }
      return GRANTED;
    }
  }
  // A matching queued op is a retry. A new op is a new logical payload RAM
  // operation, even if it must wait behind older work or this cycle's grant.
  int pending_index = -1;
  for (unsigned i = 0; i < m_pending[bank].size(); ++i)
    if (m_pending[bank][i].r == r && m_pending[bank][i].id == id &&
        m_pending[bank][i].write == write) pending_index = i;
  if (pending_index >= 0) ++m_bank_retry_attempts;

  // No selected older op, no queued older op, and no operation consumed on
  // this bank this cycle: the first ready op uses an idle bank immediately.
  // There is no reason to stage it until N+1 merely to wait for hypothetical
  // later arrivals in the same cycle.
  if (m_granted[bank].empty() && m_pending[bank].empty() &&
      !m_bank_granted.test(bank)) {
    assert(pending_index < 0);
    record_logical_operation(bank, op_class);
    m_bank_granted.set(bank); ++m_bank_grants; ++m_bank_grants_by_bank[bank];
    return GRANTED;
  }

  if (pending_index < 0) {
    record_logical_operation(bank, op_class);
    m_pending[bank].push_back(pending_op(
        r, id, write,
        sequence == (unsigned long long)-1 ? m_next_sequence++ : sequence,
        cycle));
    pending_index = m_pending[bank].size() - 1;
  }
  // This denial has a real physical reason: an older selected/pending op,
  // or an operation already consumed this cycle.  It is no longer used for
  // first-idle-op staging bookkeeping.
  pending_op &denied = m_pending[bank][pending_index];
  if (!denied.true_conflict) {
    denied.true_conflict = true;
    denied.first_conflict_cycle = cycle;
    ++m_bank_true_conflict_ops;
    ++m_bank_true_conflict_ops_by_bank[bank];
  }
  ++m_bank_true_conflict_events;
  ++m_bank_true_conflict_events_by_bank[bank];
  return BANK_TRUE_CONTENTION;
}

void memory_sub_partition::cache_cycle(unsigned cycle) {
  // L2 fill responses
  if (!m_config->m_L2_config.disabled()) {
    if (m_l2_char_collector)
      m_l2_char_collector->record_mshr_response(
          m_L2cache->access_ready(),
          m_L2cache->access_ready() && m_L2_icnt_queue->full());
    if (m_L2cache->access_ready() && !m_L2_icnt_queue->full() &&
        m_L2cache->ft_response_ready(m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle)) {
      // Keep the EP-L2 descriptor live until this response has actually been
      // accepted by the L2->ICNT queue below.
      mem_fetch *mf = m_L2cache->peek_next_access();
      if (mf->get_access_type() !=
          L2_WR_ALLOC_R) {  // Don't pass write allocate read request back to
                            // upper level cache
        mf->set_reply();
        mf->set_status(IN_PARTITION_L2_TO_ICNT_QUEUE,
                       m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
        ep_l2_m0a_record_response_enqueue();
        ft_record_response(mf);
        m_L2_icnt_queue->push(mf);
      } else {
        if (m_config->m_L2_config.m_write_alloc_policy == FETCH_ON_WRITE) {
          mem_fetch *original_wr_mf = mf->get_original_wr_mf();
          assert(original_wr_mf);
          original_wr_mf->set_reply();
          original_wr_mf->set_status(
              IN_PARTITION_L2_TO_ICNT_QUEUE,
              m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
          ep_l2_m0a_record_response_enqueue();
          ft_record_response(original_wr_mf);
          m_L2_icnt_queue->push(original_wr_mf);
        }
        m_request_tracker.erase(mf);
        delete mf;
      }
      m_L2cache->commit_next_access();
    }
  }

enum cache_request_status l2_cache::ft_access(new_addr_type addr, mem_fetch *mf,
    unsigned time, std::list<cache_event> &events) {
  // memcpy offset orders native Tag timestamps; it is not elapsed hardware
  // time and must never reset the payload bank arbiter or WB/WAD lifetimes.
  const unsigned long long physical_cycle = ft_physical_cycle();
  m_ep_l2_last_payload_request_result = ep_l2_payload_store::GRANTED;
  const new_addr_type owner = m_config.block_addr(addr);
  unsigned index = (unsigned)-1;
  cache_request_status probe = m_tag_array->probe(owner, index, mf, mf->is_write(), true);
  if (probe == RESERVATION_FAIL) return RESERVATION_FAIL;
  if (m_ft_pending.request && m_ft_pending.request != mf) return RESERVATION_FAIL;
  if (ep_l2_wad_contains(owner)) { ++m_ep_l2_wad_same_address_wait_count; return RESERVATION_FAIL; }

  if (probe == MISS && !m_ft_pending.request) {
    // Retire completed invalidated tag identities (e.g. a kernel flush), never
    // a pinned response or a live pending sector. No address-wide RO cleanup.
    for (unsigned t = 0; t < m_config.get_num_lines(); ++t) {
      const ep_l2::PayloadHandle h = tag_payload_handle(t);
      if (!m_ep_l2_payload.handle_live(h)) continue;
      const ep_l2_payload_store::slot &s = m_ep_l2_payload.inspect(h);
      if (s.allocation_role == ep_l2_payload_store::RESIDENT &&
          m_tag_array->get_block(t)->is_invalid_line() && !s.pins && s.pending_sector_mask.none()) {
        m_ep_l2_payload.release(h); set_tag_payload_handle(t, ep_l2::PayloadHandle());
      }
    }
    const ep_l2::PayloadHandle victim = tag_payload_handle(index);
    const bool live = m_ep_l2_payload.handle_live(victim);
    const bool dirty = m_tag_array->block_is_modified(index);
    if (live && (m_ep_l2_payload.inspect(victim).pins ||
                 m_ep_l2_payload.inspect(victim).pending_sector_mask.any())) {
      ++m_ft_stats.pin_block; return RESERVATION_FAIL;
    }
    assert(!dirty || live);
    // Compute the actual target policy's issue needs before acquiring anything.
    const bool read = !mf->get_is_write();
    const new_addr_type key = m_config.mshr_addr(addr);
    unsigned slots = dirty ? 1 : 0;
    if (read) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      if (m_mshrs.needs_lower_read(key, mf->get_access_sector_mask())) ++slots;
    } else if (m_config.m_write_alloc_policy == WRITE_ALLOCATE) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      slots += 2;
    } else if (m_config.m_write_alloc_policy == FETCH_ON_WRITE &&
               mf->get_access_byte_mask().count() != m_config.get_atom_sz()) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      ++slots;
    }
    if (!miss_queue_has_slots(slots)) { ++m_ft_stats.issue_block; return RESERVATION_FAIL; }
    if (dirty && m_ep_l2_wad_entries_live.size() >= m_config.m_ep_l2_wad_entries) {
      ++m_ep_l2_wad_full_block_count; return RESERVATION_FAIL;
    }
    ep_l2::PayloadHandle staging, landing;
    if (dirty && m_config.m_ep_l2_ft_mode == 1) {
      staging = m_ep_l2_payload.preview_free(ep_l2_payload_store::WB);
      if (!staging.valid()) { ++m_ft_stats.wbuf_full; return RESERVATION_FAIL; }
    }
    if (m_config.m_ep_l2_ft_mode == 2 && (dirty || !live)) {
      landing = m_ep_l2_payload.preview_free(ep_l2_payload_store::RESIDENT, index % 4);
      if (!landing.valid()) { ++m_ft_stats.pool_full; return RESERVATION_FAIL; }
      if (dirty) staging = victim;
    }
    // The only producer is the serialized frontend head. While this token is
    // live no other frontend request can steal its prechecked issue slots;
    // fills and lower drains cannot add entries to m_miss_queue.
    ft_replacement &p = m_ft_pending;
    p.request = mf; p.tag_index = index; p.dirty = dirty; p.victim = live ? victim : ep_l2::PayloadHandle();
    p.born = physical_cycle;
    p.landing_id = landing.valid() ? landing.payload_id :
        (m_config.m_ep_l2_ft_mode == 2 && live ? victim.payload_id : index);
    if (live) p.saved = m_ep_l2_payload.inspect(victim);
    if (dirty) {
      p.victim_address = m_tag_array->get_block(index)->m_block_addr;
      assert(m_ep_l2_wad_entries_live.insert(p.victim_address).second);
      assert(m_ep_l2_wad_birth_cycle.insert(std::make_pair(p.victim_address, physical_cycle)).second);
      p.wad = true;
      if (m_config.m_ep_l2_ft_mode == 1)
        p.staging = m_ep_l2_payload.reserve(staging.payload_id,
            ep_l2_payload_store::WB, p.victim_address, ep_l2_payload_store::WB_RESERVED);
      else p.staging = staging;
    }
    if (landing.valid()) {
      p.landing = m_ep_l2_payload.reserve(landing.payload_id,
          ep_l2_payload_store::RESIDENT, owner, ep_l2_payload_store::RESIDENT_FILL_PENDING);
      p.landing_reserved = true;
    }
  }

  bool replacement = m_ft_pending.request == mf;
  if (replacement) {
    ft_replacement &p = m_ft_pending;
    assert(p.tag_index == index && probe == MISS);
    if (p.dirty && m_config.m_ep_l2_ft_mode == 1) {
      // A shared, explicitly costed 128B copy-pipeline latch bridges same-bank
      // read and write cycles. Both compared organizations include this latch.
      if (p.phase == 0) {
        m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.victim,
            false, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::WB_READOUT);
        if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
          ++m_ft_stats.bank_block; return RESERVATION_FAIL;
        }
        p.born = physical_cycle; // actual source readout starts data-staging lifetime
        p.copy_versions = m_ep_l2_payload.inspect(p.victim).versions;
        p.phase = 1;
        return RESERVATION_FAIL;
      }
      if (p.phase == 1) {
        m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.staging,
            true, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::RESIDENT_WRITE);
        if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
          ++m_ft_stats.bank_block; return RESERVATION_FAIL;
        }
        m_ep_l2_payload.inspect_mutable(p.staging).versions = p.copy_versions;
        m_ep_l2_payload.transfer(p.staging, ep_l2_payload_store::WB, ep_l2_payload_store::WB_STAGED);
        ++m_ft_stats.copy_lines; p.phase = 2;
      }
    }
    // Locally absorbed writes consume an actual payload RAM write. Request
    // the stable prospective ID before changing victim/tag ownership, so a
    // same-bank denial cannot expose a partially installed new generation.
    if (mf->get_is_write()) {
      m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(
          ep_l2_payload_store::RESIDENT, p.landing_id, true, physical_cycle,
          (unsigned long long)-1, ep_l2_payload_store::RESIDENT_WRITE);
      if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
        ++m_ft_stats.bank_block; return RESERVATION_FAIL;
      }
    }
    if (p.dirty && m_config.m_ep_l2_ft_mode == 2) {
      p.born = physical_cycle; // in-place WB role starts at actual producer commit
      m_ep_l2_payload.transfer(p.victim, ep_l2_payload_store::WB, ep_l2_payload_store::WB_STAGED);
      if (p.victim.payload_id < 1024) ++m_ft_stats.borrow_resident;
      else if (p.victim.payload_id < 1152) ++m_ft_stats.borrow_bypass;
    }
    if (!p.landing_reserved) {
      const unsigned id = p.landing_id;
      if (m_ep_l2_payload.handle_live(p.victim)) m_ep_l2_payload.release(p.victim);
      p.landing = m_ep_l2_payload.reserve(id, ep_l2_payload_store::RESIDENT,
          owner, ep_l2_payload_store::RESIDENT_FILL_PENDING);
      p.landing_reserved = true;
    }
    set_tag_payload_handle(index, p.landing);
  } else {
    const ep_l2::PayloadHandle h = tag_payload_handle(index);
    assert(m_ep_l2_payload.handle_owner_matches(h, owner));
    if ((mf->get_is_write() || mf->isatomic()) && m_ep_l2_payload.inspect(h).pins) {
      ++m_ft_stats.pin_block; return RESERVATION_FAIL;
    }
    if (probe == HIT || mf->get_is_write()) {
      m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(h,
          mf->get_is_write() || mf->isatomic(), physical_cycle, (unsigned long long)-1,
          mf->get_is_write() || mf->isatomic() ? ep_l2_payload_store::RESIDENT_WRITE : ep_l2_payload_store::RESIDENT_HIT_READ);
      if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
        ++m_ft_stats.bank_block; return RESERVATION_FAIL;
      }
    }
  }
  const ep_l2::PayloadHandle handle = tag_payload_handle(index);
  mf->set_ep_l2_payload_identity(handle.payload_id, handle.generation);
  const cache_request_status result = data_cache::access(addr, mf, time, events);
  if (result == RESERVATION_FAIL) {
    if (replacement) ft_rollback();
    return result;
  }
  if (replacement && m_ft_pending.dirty) assert(m_ft_pending.bound);
  ep_l2_payload_store::slot &slot = m_ep_l2_payload.inspect_mutable(handle);
  if (mf->get_is_write() || (mf->isatomic() && probe == HIT)) {
    for (unsigned s = 0; s < 4; ++s)
      if (mf->get_access_sector_mask().test(s)) slot.versions[s] = (unsigned long long)mf->get_request_uid() + 1;
    if (mf->get_access_byte_mask().count() == m_config.get_atom_sz() || probe == HIT)
      slot.ready_sector_mask |= mf->get_access_sector_mask();
  }
  if (m_tag_array->block_is_modified(index)) slot.status = ep_l2_payload_store::RESIDENT_DIRTY;
  else if (slot.pending_sector_mask.none()) slot.status = ep_l2_payload_store::RESIDENT_VALID;
  if (!mf->get_is_write()) mf->set_ft_wb_data(slot.versions);
  if (replacement) m_ft_pending = ft_replacement();
  ++m_ft_stats.accepted;
  m_tag_array->l2_char_tracking_refresh_line(index);
  assert(m_ep_l2_payload.ownership_consistent());
  return result;
}

      if (plan.exact && !admit) {
        unsigned long long blockers = l2_admission_blockers(admission);
        if (!blockers) blockers = 1ULL << L2_BLOCK_OTHER;
        m_l2_char_stats.record_blockers(
            mf, blockers, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle,
            m_l2_block_state);
        if (plan.ep_l2_mshr_block_reason != mshr_table::EP_L2_BLOCK_NONE)
          ++m_ep_l2_b0_accum.descriptor_block;
        // Compatibility fields remain coarse; C7d consumers must use the
        // explicitly named exact fields above instead of reinterpreting them.
        if (plan.ep_l2_wad_full || plan.ep_l2_wad_same_address_hazard)
          ++m_ep_l2_b0_accum.wad_block;
        if (plan.new_missq_entries && !admission.missq_available)
          ++m_ep_l2_b0_accum.missq_full_block;
        if (plan.will_send_lower_read && m_L2_dram_queue->full()) {
          ++m_ep_l2_b0_accum.lower_block;
          ++m_ep_l2_b0_accum.l2_to_dram_full_block;
        }

        if (plan.needs_data_port && !admission.data_port_available &&
            plan.is_read && plan.probe_status == HIT)
          m_l2_char_stats.dataport_hit_block_cycles++;

        // A dirty victim consumes two MissQ entries (writeback plus demand).
        // When precisely one entry remains, refusal must be completely
        // side-effect free: previewing again must see the same cache and
        // queue state because access() was never called.
        if (plan.victim_dirty && plan.new_missq_entries == 2 &&
            missq_one_slot_before) {
          m_l2_char_stats.missq_dirty_miss_block_one_slot++;
          l2_access_plan retry_plan;
          m_L2cache->preview_access(mf->get_addr(), mf, retry_plan);
          const bool unchanged =
              m_L2cache->miss_queue_occupancy() == missq_occupancy_before &&
              m_L2cache->mshr_entries_used() == mshr_entries_before &&
              retry_plan.probe_status == plan.probe_status &&
              retry_plan.cache_index == plan.cache_index &&
              retry_plan.victim_valid == plan.victim_valid &&
              retry_plan.victim_dirty == plan.victim_dirty &&
              retry_plan.needs_new_mshr == plan.needs_new_mshr &&
              retry_plan.needs_mshr_merge == plan.needs_mshr_merge &&
              retry_plan.new_missq_entries == plan.new_missq_entries &&
              retry_plan.will_send_lower_read == plan.will_send_lower_read &&
              retry_plan.ep_l2_mshr_block_reason ==
                  plan.ep_l2_mshr_block_reason &&
              retry_plan.ep_l2_needs_lower_read == plan.ep_l2_needs_lower_read &&
              retry_plan.will_send_writeback == plan.will_send_writeback;
          if (unchanged)
            m_l2_char_stats.missq_dirty_block_no_mutation++;
          else
            m_l2_char_stats.missq_dirty_block_partial_mutation++;
#ifndef NDEBUG
          assert(unchanged);
#endif
        }
      }

void baseline_cache::cycle() {
  if (!m_miss_queue.empty()) {
    mem_fetch *mf = m_miss_queue.front();
    if (!m_memport->full(mf->size(), mf->get_is_write()) &&
        lower_ready(mf, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle)) {
      m_miss_queue.pop_front();
      m_memport->push(mf);
      lower_accepted(mf, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
    }
  }
  bool data_port_busy = !m_bandwidth_management.data_port_free();
  bool fill_port_busy = !m_bandwidth_management.fill_port_free();
  // Keep the characterization observation aligned with the native statistics.
  // This is intentionally before replenish_port_bandwidth(); it must not affect
  // availability, admission, or fill semantics later in this cache cycle.
  m_l2_char_data_port_busy_snapshot = data_port_busy;
  m_l2_char_fill_port_busy_snapshot = fill_port_busy;
  m_stats.sample_cache_port_utility(data_port_busy, fill_port_busy);
  m_bandwidth_management.replenish_port_bandwidth();
}

bool l2_cache::lower_ready(mem_fetch *mf, unsigned long long cycle) {
  if (!ft_enabled() || mf->get_access_type() != L2_WRBK_ACC) return true;
  std::map<mem_fetch *,ft_wb_record>::iterator it = m_ft_wb.find(mf);
  assert(it != m_ft_wb.end());
  const ep_l2_payload_store::request_result result = m_ep_l2_payload.request(
      it->second.handle, false, cycle, (unsigned long long)-1, ep_l2_payload_store::WB_READOUT);
  if (result != ep_l2_payload_store::GRANTED) { ++m_ft_stats.bank_block; return false; }
  assert(m_ep_l2_payload.inspect(it->second.handle).versions == it->second.expected);
  m_ft_last_wb_versions = it->second.expected;
  mf->set_ft_wb_data(it->second.expected);
  ++m_ft_stats.staging_reads; ++m_ft_stats.data_checks;
  return true;
}

request_result request(role r, unsigned id, bool write, unsigned long long cycle,
                       unsigned long long sequence = (unsigned long long)-1,
                       operation_class op_class = RESIDENT_HIT_READ) {
  if (!enabled()) return GRANTED;
  if (m_ft_mode && m_cycle != (unsigned long long)-1)
    assert(cycle >= m_cycle && "FT bank clock must be physical and monotonic");
  if (m_cycle != cycle) {
    m_cycle = cycle;
    m_resident_reads = m_resident_writes = m_bypass_reads = m_bypass_writes = 0;
    std::fill(m_bank_services, m_bank_services+4, 0);
    if (banked()) {
      for (unsigned b = 0; b < 4; ++b) {
        // A production retry need not return in the single cycle after it
        // was selected.  Retain an unconsumed oldest grant until its owner
        // actually retries; with P2 retain up to two identities, then fill
        // unused selections from the oldest pending list. Clearing loses
        // the request. Two
        // interleaved same-bank retries would otherwise select-and-discard
        // each other forever, eventually deadlocking the memory system.
        while (m_granted[b].size() < m_bank_ops && !m_pending[b].empty()) {
          unsigned best = 0;
          for (unsigned i = 1; i < m_pending[b].size(); ++i)
            if (m_pending[b][i].sequence < m_pending[b][best].sequence) best = i;
          m_granted[b].push_back(m_pending[b][best]);
          m_pending[b].erase(m_pending[b].begin() + best);
        }
      }
    }
  }
  if (m_mode == 1) {
    unsigned &used_port = r == RESIDENT ?
        (write ? m_resident_writes : m_resident_reads) :
        (write ? m_bypass_writes : m_bypass_reads);
    if (used_port) return LEGACY_PORT_BUSY;
    ++used_port; return GRANTED;
  }
  const unsigned global_id = r == BYPASS ? k_resident_slots + id : id;
  assert(r != BYPASS || id < bypass_capacity());
  assert(global_id < m_slots.size());
  const unsigned bank = global_id % 4;
  ++m_bank_attempts;
  for (unsigned selected=0; selected<m_granted[bank].size(); ++selected) {
    const pending_op op = m_granted[bank][selected];
    if (op.r == r && op.id == id && op.write == write) {
      // Its first call was accounted as the logical operation.  This call
      // is the retry that finally consumes an oldest-ready grant.
      ++m_bank_retry_attempts;
      m_granted[bank].erase(m_granted[bank].begin()+selected); consume_bank(bank); ++m_bank_grants;
      ++m_bank_grants_by_bank[bank];
      if (op.true_conflict) {
        const unsigned long long waited = cycle - op.first_conflict_cycle;
        m_bank_wait_cycles += waited;
        m_bank_wait_cycles_by_bank[bank] += waited;
      }
      return GRANTED;
    }
  }
  // A matching queued op is a retry. A new op is a new logical payload RAM
  // operation, even if it must wait behind older work or this cycle's grant.
  int pending_index = -1;
  for (unsigned i = 0; i < m_pending[bank].size(); ++i)
    if (m_pending[bank][i].r == r && m_pending[bank][i].id == id &&
        m_pending[bank][i].write == write) pending_index = i;
  if (pending_index >= 0) ++m_bank_retry_attempts;

  // No selected/queued older op: a ready operation may consume one of the
  // finite remaining services of this bank in this physical cycle.
  // There is no reason to stage it until N+1 merely to wait for hypothetical
  // later arrivals in the same cycle.
  if (m_granted[bank].empty() && m_pending[bank].empty() &&
      m_bank_services[bank] < m_bank_ops) {
    assert(pending_index < 0);
    record_logical_operation(bank, op_class);
    consume_bank(bank); ++m_bank_grants; ++m_bank_grants_by_bank[bank];
    return GRANTED;
  }

  if (pending_index < 0) {
    record_logical_operation(bank, op_class);
    m_pending[bank].push_back(pending_op(
        r, id, write,
        sequence == (unsigned long long)-1 ? m_next_sequence++ : sequence,
        cycle));
    pending_index = m_pending[bank].size() - 1;
  }
  // This denial has a real physical reason: an older selected/pending op,
  // or an operation already consumed this cycle.  It is no longer used for
  // first-idle-op staging bookkeeping.
  pending_op &denied = m_pending[bank][pending_index];
  if (!denied.true_conflict) {
    denied.true_conflict = true;
    denied.first_conflict_cycle = cycle;
    ++m_bank_true_conflict_ops;
    ++m_bank_true_conflict_ops_by_bank[bank];
  }
  ++m_bank_true_conflict_events;
  ++m_bank_true_conflict_events_by_bank[bank];
  return BANK_TRUE_CONTENTION;
}

void memory_sub_partition::cache_cycle(unsigned cycle) {
  // L2 fill responses
  if (!m_config->m_L2_config.disabled()) {
    if (m_l2_char_collector)
      m_l2_char_collector->record_mshr_response(
          m_L2cache->access_ready(),
          m_L2cache->access_ready() && m_L2_icnt_queue->full());
    if (m_L2cache->access_ready() && !m_L2_icnt_queue->full() &&
        m_L2cache->ft_response_ready(m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle)) {
      // Keep the EP-L2 descriptor live until this response has actually been
      // accepted by the L2->ICNT queue below.
      mem_fetch *mf = m_L2cache->peek_next_access();
      if (mf->get_access_type() !=
          L2_WR_ALLOC_R) {  // Don't pass write allocate read request back to
                            // upper level cache
        mf->set_reply();
        mf->set_status(IN_PARTITION_L2_TO_ICNT_QUEUE,
                       m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
        ep_l2_m0a_record_response_enqueue();
        ft_record_response(mf);
        m_L2_icnt_queue->push(mf);
      } else {
        if (m_config->m_L2_config.m_write_alloc_policy == FETCH_ON_WRITE) {
          mem_fetch *original_wr_mf = mf->get_original_wr_mf();
          assert(original_wr_mf);
          original_wr_mf->set_reply();
          original_wr_mf->set_status(
              IN_PARTITION_L2_TO_ICNT_QUEUE,
              m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle);
          ep_l2_m0a_record_response_enqueue();
          ft_record_response(original_wr_mf);
          m_L2_icnt_queue->push(original_wr_mf);
        }
        m_request_tracker.erase(mf);
        m_ideal_arrivals.erase(mf);
        delete mf;
      }
      m_L2cache->commit_next_access();
    }
  }

enum cache_request_status l2_cache::ft_access(new_addr_type addr, mem_fetch *mf,
    unsigned time, std::list<cache_event> &events) {
  // memcpy offset orders native Tag timestamps; it is not elapsed hardware
  // time and must never reset the payload bank arbiter or WB/WAD lifetimes.
  ft_assert_quota();
  if (m_ft_pending.request == mf && m_ft_pending.quota_reserved) ++m_ft_quota.retries;
  const unsigned long long physical_cycle = ft_physical_cycle();
  m_ep_l2_last_payload_request_result = ep_l2_payload_store::GRANTED;
  const new_addr_type owner = m_config.block_addr(addr);
  unsigned index = (unsigned)-1;
  cache_request_status probe = m_tag_array->probe(owner, index, mf, mf->is_write(), true);
  if (probe == RESERVATION_FAIL) return RESERVATION_FAIL;
  if (m_ft_pending.request && m_ft_pending.request != mf) return RESERVATION_FAIL;
  if (ep_l2_wad_contains(owner)) { ++m_ep_l2_wad_same_address_wait_count; return RESERVATION_FAIL; }

  if (probe == MISS && !m_ft_pending.request) {
    // Retire completed invalidated tag identities (e.g. a kernel flush), never
    // a pinned response or a live pending sector. No address-wide RO cleanup.
    for (unsigned t = 0; t < m_config.get_num_lines(); ++t) {
      const ep_l2::PayloadHandle h = tag_payload_handle(t);
      if (!m_ep_l2_payload.handle_live(h)) continue;
      const ep_l2_payload_store::slot &s = m_ep_l2_payload.inspect(h);
      if (s.allocation_role == ep_l2_payload_store::RESIDENT &&
          m_tag_array->get_block(t)->is_invalid_line() && !s.pins && s.pending_sector_mask.none()) {
        m_ep_l2_payload.release(h); set_tag_payload_handle(t, ep_l2::PayloadHandle());
      }
    }
    const ep_l2::PayloadHandle victim = tag_payload_handle(index);
    const bool live = m_ep_l2_payload.handle_live(victim);
    const bool dirty = m_tag_array->block_is_modified(index);
    if (live && (m_ep_l2_payload.inspect(victim).pins ||
                 m_ep_l2_payload.inspect(victim).pending_sector_mask.any())) {
      ++m_ft_stats.pin_block; return RESERVATION_FAIL;
    }
    assert(!dirty || live);
    // Compute the actual target policy's issue needs before acquiring anything.
    const bool read = !mf->get_is_write();
    const new_addr_type key = m_config.mshr_addr(addr);
    unsigned slots = dirty ? 1 : 0;
    if (read) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      if (m_mshrs.needs_lower_read(key, mf->get_access_sector_mask())) ++slots;
    } else if (m_config.m_write_alloc_policy == WRITE_ALLOCATE) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      slots += 2;
    } else if (m_config.m_write_alloc_policy == FETCH_ON_WRITE &&
               mf->get_access_byte_mask().count() != m_config.get_atom_sz()) {
      if (m_mshrs.full(key)) return RESERVATION_FAIL;
      ++slots;
    }
    if (!miss_queue_has_slots(slots)) { ++m_ft_stats.issue_block; return RESERVATION_FAIL; }
    if (dirty && m_ep_l2_wad_entries_live.size() >= m_config.m_ep_l2_wad_entries) {
      ++m_ep_l2_wad_full_block_count; return RESERVATION_FAIL;
    }
    ep_l2::PayloadHandle staging, landing;
    if (dirty && m_config.m_ep_l2_ft_mode == 1) {
      staging = m_ep_l2_payload.preview_free(ep_l2_payload_store::WB);
      if (!staging.valid()) { ++m_ft_stats.wbuf_full; return RESERVATION_FAIL; }
    }
    if (m_config.m_ep_l2_ft_mode == 2 && (dirty || !live)) {
      landing = m_ep_l2_payload.preview_free(ep_l2_payload_store::RESIDENT, index % 4);
      if (!landing.valid()) { ++m_ft_stats.pool_full; return RESERVATION_FAIL; }
      if (dirty) staging = victim;
    }
    // All issue/WAD/staging/landing prechecks passed. Reserve quota before
    // exposing any cross-cycle transaction; retries keep this one token.
    if (dirty && m_config.m_ep_l2_wb_local_cap &&
        m_ft_quota.reserved + m_ft_quota.live >= m_config.m_ep_l2_wb_local_cap) {
      ++m_ft_quota.refusals; return RESERVATION_FAIL;
    }
    // The only producer is the serialized frontend head. While this token is
    // live no other frontend request can steal its prechecked issue slots;
    // fills and lower drains cannot add entries to m_miss_queue.
    ft_replacement &p = m_ft_pending;
    p.request = mf; p.tag_index = index; p.dirty = dirty; p.victim = live ? victim : ep_l2::PayloadHandle();
    p.born = physical_cycle;
    p.landing_id = landing.valid() ? landing.payload_id :
        (m_config.m_ep_l2_ft_mode == 2 && live ? victim.payload_id : index);
    if (live) p.saved = m_ep_l2_payload.inspect(victim);
    if (dirty) {
      if (m_config.m_ep_l2_wb_local_cap) {
        assert(!m_ft_quota.reserved); ++m_ft_quota.reserved; p.quota_reserved = true;
        m_ft_quota.reserved_peak = std::max(m_ft_quota.reserved_peak, m_ft_quota.reserved);
        m_ft_quota.total_peak = std::max(m_ft_quota.total_peak, m_ft_quota.reserved + m_ft_quota.live);
      }
      p.victim_address = m_tag_array->get_block(index)->m_block_addr;
      assert(m_ep_l2_wad_entries_live.insert(p.victim_address).second);
      assert(m_ep_l2_wad_birth_cycle.insert(std::make_pair(p.victim_address, physical_cycle)).second);
      p.wad = true;
      if (m_config.m_ep_l2_ft_mode == 1)
        p.staging = m_ep_l2_payload.reserve(staging.payload_id,
            ep_l2_payload_store::WB, p.victim_address, ep_l2_payload_store::WB_RESERVED);
      else p.staging = staging;
    }
    if (landing.valid()) {
      p.landing = m_ep_l2_payload.reserve(landing.payload_id,
          ep_l2_payload_store::RESIDENT, owner, ep_l2_payload_store::RESIDENT_FILL_PENDING);
      p.landing_reserved = true;
    }
  }

  bool replacement = m_ft_pending.request == mf;
  if (replacement) {
    ft_replacement &p = m_ft_pending;
    assert(p.tag_index == index && probe == MISS);
    if (p.dirty && m_config.m_ep_l2_ft_mode == 1) {
      // A shared, explicitly costed 128B copy-pipeline latch bridges same-bank
      // read and write cycles. Both compared organizations include this latch.
      if (p.phase == 0) {
        m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.victim,
            false, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::WB_READOUT);
        if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
          ++m_ft_stats.bank_block; return RESERVATION_FAIL;
        }
        p.born = physical_cycle; // actual source readout starts data-staging lifetime
        p.copy_versions = m_ep_l2_payload.inspect(p.victim).versions;
        p.phase = 1;
        return RESERVATION_FAIL;
      }
      if (p.phase == 1) {
        m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.staging,
            true, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::RESIDENT_WRITE);
        if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
          ++m_ft_stats.bank_block; return RESERVATION_FAIL;
        }
        m_ep_l2_payload.inspect_mutable(p.staging).versions = p.copy_versions;
        m_ep_l2_payload.transfer(p.staging, ep_l2_payload_store::WB, ep_l2_payload_store::WB_STAGED);
        ++m_ft_stats.copy_lines; p.phase = 2;
      }
    }
    // Locally absorbed writes consume an actual payload RAM write. Request
    // the stable prospective ID before changing victim/tag ownership, so a
    // same-bank denial cannot expose a partially installed new generation.
    if (mf->get_is_write()) {
      m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(
          ep_l2_payload_store::RESIDENT, p.landing_id, true, physical_cycle,
          (unsigned long long)-1, ep_l2_payload_store::RESIDENT_WRITE);
      if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
        ++m_ft_stats.bank_block; return RESERVATION_FAIL;
      }
    }
    if (p.dirty && m_config.m_ep_l2_ft_mode == 2) {
      p.born = physical_cycle; // in-place WB role starts at actual producer commit
      m_ep_l2_payload.transfer(p.victim, ep_l2_payload_store::WB, ep_l2_payload_store::WB_STAGED);
      if (p.victim.payload_id < 1024) ++m_ft_stats.borrow_resident;
      else if (p.victim.payload_id < 1152) ++m_ft_stats.borrow_bypass;
    }
    if (!p.landing_reserved) {
      const unsigned id = p.landing_id;
      if (m_ep_l2_payload.handle_live(p.victim)) m_ep_l2_payload.release(p.victim);
      p.landing = m_ep_l2_payload.reserve(id, ep_l2_payload_store::RESIDENT,
          owner, ep_l2_payload_store::RESIDENT_FILL_PENDING);
      p.landing_reserved = true;
    }
    set_tag_payload_handle(index, p.landing);
  } else {
    const ep_l2::PayloadHandle h = tag_payload_handle(index);
    assert(m_ep_l2_payload.handle_owner_matches(h, owner));
    if ((mf->get_is_write() || mf->isatomic()) && m_ep_l2_payload.inspect(h).pins) {
      ++m_ft_stats.pin_block; return RESERVATION_FAIL;
    }
    if (probe == HIT || mf->get_is_write()) {
      m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(h,
          mf->get_is_write() || mf->isatomic(), physical_cycle, (unsigned long long)-1,
          mf->get_is_write() || mf->isatomic() ? ep_l2_payload_store::RESIDENT_WRITE : ep_l2_payload_store::RESIDENT_HIT_READ);
      if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
        ++m_ft_stats.bank_block; return RESERVATION_FAIL;
      }
    }
  }
  const ep_l2::PayloadHandle handle = tag_payload_handle(index);
  mf->set_ep_l2_payload_identity(handle.payload_id, handle.generation);
  const cache_request_status result = data_cache::access(addr, mf, time, events);
  if (result == RESERVATION_FAIL) {
    if (replacement) ft_rollback();
    return result;
  }
  if (replacement && m_ft_pending.dirty) assert(m_ft_pending.bound);
  ep_l2_payload_store::slot &slot = m_ep_l2_payload.inspect_mutable(handle);
  if (mf->get_is_write() || (mf->isatomic() && probe == HIT)) {
    for (unsigned s = 0; s < 4; ++s)
      if (mf->get_access_sector_mask().test(s)) slot.versions[s] = (unsigned long long)mf->get_request_uid() + 1;
    if (mf->get_access_byte_mask().count() == m_config.get_atom_sz() || probe == HIT)
      slot.ready_sector_mask |= mf->get_access_sector_mask();
  }
  if (m_tag_array->block_is_modified(index)) slot.status = ep_l2_payload_store::RESIDENT_DIRTY;
  else if (slot.pending_sector_mask.none()) slot.status = ep_l2_payload_store::RESIDENT_VALID;
  if (!mf->get_is_write()) mf->set_ft_wb_data(slot.versions);
  if (replacement) m_ft_pending = ft_replacement();
  ++m_ft_stats.accepted;
  m_tag_array->l2_char_tracking_refresh_line(index);
  assert(m_ep_l2_payload.ownership_consistent());
  return result;
}

      if (plan.exact && !admit) {
        unsigned long long blockers = l2_admission_blockers(admission);
        if (!blockers) blockers = 1ULL << L2_BLOCK_OTHER;
        m_l2_char_stats.record_blockers(
            mf, blockers, m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle,
            m_l2_block_state);
        if (plan.ep_l2_mshr_block_reason != mshr_table::EP_L2_BLOCK_NONE)
          ++m_ep_l2_b0_accum.descriptor_block;
        // Compatibility fields remain coarse; C7d consumers must use the
        // explicitly named exact fields above instead of reinterpreting them.
        if (plan.ep_l2_wad_full || plan.ep_l2_wad_same_address_hazard)
          ++m_ep_l2_b0_accum.wad_block;
        if (plan.new_missq_entries && !admission.missq_available)
          ++m_ep_l2_b0_accum.missq_full_block;
        if (plan.will_send_lower_read && m_L2_dram_queue->full()) {
          ++m_ep_l2_b0_accum.lower_block;
          ++m_ep_l2_b0_accum.l2_to_dram_full_block;
        }

        if (plan.needs_data_port && !admission.data_port_available &&
            plan.is_read && plan.probe_status == HIT)
          m_l2_char_stats.dataport_hit_block_cycles++;

        // A dirty victim consumes two MissQ entries (writeback plus demand).
        // When precisely one entry remains, refusal must be completely
        // side-effect free: previewing again must see the same cache and
        // queue state because access() was never called.
        if (plan.victim_dirty && plan.new_missq_entries == 2 &&
            missq_one_slot_before) {
          m_l2_char_stats.missq_dirty_miss_block_one_slot++;
          l2_access_plan retry_plan;
          m_L2cache->preview_access(mf->get_addr(), mf, retry_plan);
          const bool unchanged =
              m_L2cache->miss_queue_occupancy() == missq_occupancy_before &&
              m_L2cache->mshr_entries_used() == mshr_entries_before &&
              retry_plan.probe_status == plan.probe_status &&
              retry_plan.cache_index == plan.cache_index &&
              retry_plan.victim_valid == plan.victim_valid &&
              retry_plan.victim_dirty == plan.victim_dirty &&
              retry_plan.needs_new_mshr == plan.needs_new_mshr &&
              retry_plan.needs_mshr_merge == plan.needs_mshr_merge &&
              retry_plan.new_missq_entries == plan.new_missq_entries &&
              retry_plan.will_send_lower_read == plan.will_send_lower_read &&
              retry_plan.ep_l2_mshr_block_reason ==
                  plan.ep_l2_mshr_block_reason &&
              retry_plan.ep_l2_needs_lower_read == plan.ep_l2_needs_lower_read &&
              retry_plan.will_send_writeback == plan.will_send_writeback;
          if (unchanged)
            m_l2_char_stats.missq_dirty_block_no_mutation++;
          else
            m_l2_char_stats.missq_dirty_block_partial_mutation++;
#ifndef NDEBUG
          assert(unchanged);
#endif
        }
      }
